### 🧠 Tip:
Want it cleaner? Use a `Set` for vowels:

```javascript
function countvowels(str1) {
    const vowels = new Set(['a', 'e', 'i', 'o', 'u']);
    str1 = str1.toLowerCase();
    let number = 0;

    for (let char of str1) {
        if (vowels.has(char)) number++;
    }

    console.log("The number of vowels are " + number);
}
```

